public class METCustomerMDFPosting_FreeTextInvoiceDaily extends METCustomerMDFPosting_FreeTextInvoice
{
    TransDate shipDate;
}

Method.Source:
public TransDate parmShipDate(TransDate _shipDate = shipDate)
{
    shipDate = _shipDate;

    return shipDate;
}

Query updateQuery(Query _query)
{
    Query ret = super(_query);

    QueryBuildDataSource qbds = ret.dataSourceTable(tableNum(METCustomerMDFConsolidationTable));
    qbds.addRange(fieldNum(METCustomerMDFConsolidationTable, ConsolidationMethod)).value(queryValue(METConsolidationMethodEDT::Daily));
    qbds.addRange(fieldNum(METCustomerMDFConsolidationTable, ShipDate)).value(queryValue(shipDate));

    return ret;
}
